            'PROJECT_BILLING.WIP_LIABILITY' => ['Passività contrattuale (ricavi differiti)', 'Contract liability (deferred revenue)', 'Vertragsverbindlichkeit (passive Rechnungsabgrenzung)', 'Passif sur contrat (produits différés)'],
            'PROJECT_BILLING.WIP_BALANCED' => ['In pareggio', 'Balanced', 'Ausgeglichen', 'Équilibré'],
        ];
    }

    /**
     * @return array<string, string>
     */
    public static function all(string $locale): array
    {
        $index = match ($locale) {
            'it' => 0,
            'de' => 2,
            'fr' => 3,
            default => 1,
        };

        return array_map(static fn (array $values): string => $values[$index], self::definitions());
    }
}
